/** Original formative instruction, not the protected final examination. Correct answer is authored
 * first; delivery must permute choices. Each related replacement changes facts or the decision
 * stage. All source pins refer to required instruction and the current official instrument.
 * Completion of authoring is not TREC approval or provider time-study validation. */
import { TOPICS, ALL_UNITS } from './promulgated-contract-forms-course-form.mjs';

const refs = {
  resale: ['TREC One to Four Family Residential Contract (Resale), 20-19, effective July 1, 2026', 'https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale'],
  rules: ['22 Texas Administrative Code, TREC Rules', 'https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules'],
  occ: ['Texas Occupations Code Chapter 1101', 'https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm'],
  bc: ['Texas Business & Commerce Code Chapter 26', 'https://tcss.legis.texas.gov/resources/BC/htm/BC.26.htm'],
  limitations: ['Texas Civil Practice & Remedies Code Chapter 16', 'https://tcss.legis.texas.gov/resources/CP/htm/CP.16.htm'],
  finance: ['TREC Third Party Financing Addendum, 40-11', 'https://www.trec.texas.gov/forms/third-party-financing-addendum-0'],
  assumption: ['TREC Loan Assumption Addendum, 41-3', 'https://www.trec.texas.gov/forms/loan-assumption-addendum-0'],
  sellerFinance: ['TREC Seller Financing Addendum, 26-8', 'https://www.trec.texas.gov/forms/seller-financing-addendum-0'],
  release: ["TREC Addendum for Release of Liability on Assumed Loan and/or Restoration of Seller's VA Entitlement, 12-3", 'https://www.trec.texas.gov/forms/addendum-release-liability-assumed-loan-andor-restoration-sellers-va-entitlement'],
  lead: ['TREC Lead-Based Paint Disclosure Addendum, 56-0', 'https://www.trec.texas.gov/forms/addendum-sellers-disclosure-information-lead-based-paint-and-lead-based-paint-hazards-0'],
  environment: ['TREC Environmental Assessment, Threatened or Endangered Species and Wetlands Addendum, 28-2', 'https://www.trec.texas.gov/forms/environmental-assessment-threatened-endangered-species-and-wetlands-addendum'],
  notice: ['TREC Notice to Prospective Buyer, 58-0', 'https://www.trec.texas.gov/forms/notice-prospective-buyer-0'],
  sellerLease: ["TREC Seller's Temporary Residential Lease, 15-7", 'https://www.trec.texas.gov/forms/sellers-temporary-residential-lease'],
  buyerLease: ["TREC Buyer's Temporary Residential Lease, 16-7", 'https://www.trec.texas.gov/forms/buyers-temporary-residential-lease'],
  condo: ['TREC Residential Condominium Contract (Resale), 30-18', 'https://www.trec.texas.gov/forms/residential-condominium-contract-resale-0'],
  farm: ['TREC Farm and Ranch Contract, 25-17', 'https://www.trec.texas.gov/forms/farm-and-ranch-contract-0'],
  lot: ['TREC Unimproved Property Contract, 9-18', 'https://www.trec.texas.gov/forms/unimproved-property-contract-0'],
  incomplete: ['TREC New Home Contract (Incomplete Construction), 23-20', 'https://www.trec.texas.gov/forms/new-home-contract-incomplete-construction-0'],
  sale: ['TREC Addendum for Sale of Other Property by Buyer, 10-6', 'https://www.trec.texas.gov/forms/addendum-sale-other-property-buyer'],
  backup: ['TREC Addendum for Back-Up Contract, 11-9', 'https://www.trec.texas.gov/forms/addendum-back-contract'],
  minerals: ['TREC Addendum for Reservation of Oil, Gas and Other Minerals, 44-3', 'https://www.trec.texas.gov/sites/default/files/pdf-forms/44-3.pdf'],
  hoa: ["TREC Addendum for Property Subject to Mandatory Membership in a Property Owners Association, 36-11", 'https://www.trec.texas.gov/forms/addendum-property-subject-mandatory-membership-property-owners-association'],
  short: ['TREC Short Sale Addendum, 45-2', 'https://www.trec.texas.gov/forms/short-sale-addendum-0'],
  coastal: ['Texas Natural Resources Code Chapter 33', 'https://tcss.legis.texas.gov/resources/NR/htm/NR.33.htm'],
  housing: ['Texas Property Code Chapter 301', 'https://tcss.legis.texas.gov/resources/PR/htm/PR.301.htm'],
  occupancy: ['Texas Property Code Chapter 92', 'https://tcss.legis.texas.gov/resources/PR/htm/PR.92.htm'],
};
const rows = [];
function pair(unit, ref, section, primary, replacement, suffix = '') {
  const [source, url] = refs[ref];
  const base = `PCF-${unit}${suffix}`;
  const build = (data, kind) => Object.freeze({
    id: `${base}-${kind === 'PRIMARY' ? 'Q' : 'R'}`, kind,
    ...(kind === 'REPLACEMENT' ? { replaces: `${base}-Q` } : {}),
    tests: unit, module: `module-${unit.slice(1, 3)}`, source, section,
    sources: Object.freeze([{ url, reference: `${source}; ${section}` }]),
    prompt: data[0], choices: Object.freeze(data[1]), correctChoice: 0, rationale: data[2],
  });
  rows.push([build(primary, 'PRIMARY'), build(replacement, 'REPLACEMENT')]);
}

pair('T01U1', 'bc', '§ 26.01(a), (b)(4)',
  ['A buyer relies only on an unsigned oral promise to sell a Texas house. No exception or other enforceable writing is established. Which issue must the agent flag?', ['The statute of frauds generally requires a signed writing for enforcement of a real-estate sale agreement; counsel must evaluate the actual record and any exception.', 'The buyer’s willingness to pay removes the writing requirement.', 'An earnest-money receipt signed only by the buyer necessarily supplies the seller’s signature.', 'All oral negotiations are criminal and therefore cannot be documented.'], 'Section 26.01 requires the covered agreement or memorandum to be written and signed by the person charged or an authorized signer. A sale of real estate is covered. Do not assert an exception or universal outcome on facts not supplied.'],
  ['A seller sends a signed sale memorandum, but the agent has not checked its terms or the signer’s authority. What is the sound next step?', ['Preserve the memorandum and verify the required terms and authority; the presence of a signature alone does not resolve every formation or enforceability issue.', 'Declare the sale enforceable because any signed message satisfies every element.', 'Discard it because only a paper TREC form can ever be a writing.', 'Treat delivery of the memorandum as proof the buyer already performed the purchase.'], 'The writing requirement is an important element, not a substitute for reviewing the actual agreement and authority. The statute does not say every signed message conclusively forms an enforceable sale.']);
pair('T01U2', 'bc', '§ 26.01(a), (b)(4)',
  ['A colleague calls an otherwise potentially valid oral sale arrangement “void” solely because no qualifying writing has been found. Which correction is best?', ['Distinguish a potential barrier to enforcement under the statute of frauds from a conclusion that no agreement could ever exist; obtain legal review.', 'Use voidable instead, because every unwritten sale can be canceled only by a minor.', 'Call it fully enforceable because the parties used the word agreement.', 'Assume a later deposit automatically cures every defect.'], 'Void, voidable, and unenforceable are different classifications. Section 26.01 concerns enforceability of covered promises; missing facts and possible exceptions prevent the agent from announcing a universal legal conclusion.'],
  ['A client asks whether a disputed unwritten land deal is unenforceable or whether a claimed exception applies. What should the license holder do?', ['Identify the writing issue, preserve the communications, and refer the exception and legal effect to counsel.', 'Guarantee the client can walk away because all oral land arrangements are void.', 'Determine the exception by whether the proposed price appears fair.', 'Prepare a backdated signature page to remove the dispute.'], 'The statutory writing issue should be flagged without deciding disputed legal effect or manufacturing evidence. Counsel evaluates exceptions and the actual transaction.']);
pair('T01U3', 'resale', 'Paragraphs 1, 9B and 10A',
  ['Both parties have accepted a resale contract, but closing and funding remain three weeks away. How should its status be described?', ['A formed agreement with performance still due; signatures do not mean the sale is fully performed.', 'No contract exists until the title company funds it.', 'The buyer already owns the property because all offer signatures are present.', 'An executory contract means either party may cancel without an applicable right.'], 'Paragraph 1 contains reciprocal promises and paragraphs 9 and 10 describe later closing and possession performance. “Executed” can describe signing, so state the event precisely rather than equating signatures with full performance.'],
  ['The parties sign closing papers at 10 a.m.; funding has not occurred, and possession is agreed at closing and funding. What status belongs in the file?', ['Closing papers signed, funding and the agreed possession trigger still pending.', 'Every contractual obligation is performed because documents are signed.', 'Possession automatically passed at the first signature.', 'The original purchase contract stopped existing when closing papers were prepared.'], 'The contract distinguishes closing tasks and the closing-and-funding possession trigger. A precise event log avoids treating signing as proof of funding.']);
pair('T01U4', 'resale', 'Paragraphs 1 and 5B',
  ['A buyer has a timely paid seven-day termination option within an accepted resale contract. Which description is accurate?', ['The purchase remains an exchange of promises; the option is a conditioned termination right within it.', 'Only the seller has any duties until the option expires.', 'The buyer has no duty to deliver earnest money because the option makes the entire transaction unilateral.', 'The option itself automatically terminates the contract on day seven.'], 'Paragraph 1 states the bilateral sale promises. Paragraph 5B permits termination under its stated conditions; it neither suspends every buyer duty nor automatically cancels the sale.'],
  ['A buyer chooses not to order an inspection during a paid option period and gives no termination notice. What follows from that choice alone?', ['The inspection choice does not erase the buyer’s purchase promises or exercise the termination right.', 'Declining inspection is the equivalent of timely option termination.', 'The seller must extend the option until an inspection occurs.', 'The buyer’s earnest-money promise becomes optional.'], 'A permission to inspect and a conditioned right to terminate are not the same as the reciprocal promises of purchase and sale. The contract still governs performance.']);
pair('T01U5', 'resale', 'Paragraph 5A–B',
  ['An option period ends Sunday under the accepted contract. No amendment extends it. Which deadline rule applies to option notice?', ['The specified option deadline remains 5 p.m. local time at the property on Sunday; the money-delivery extension does not extend the option.', 'The option always extends to Monday because money-delivery deadlines can extend.', 'The notice is timely until midnight in the buyer’s time zone.', 'The notice may be delayed until escrow reopens.'], 'Paragraph 5 separately provides a weekend/holiday extension for specified money deliveries and a 5 p.m. local-property-time option termination deadline. They are not interchangeable.'],
  ['The final day to deliver earnest money under paragraph 5A is a Sunday. No other complication is supplied. Which action follows that paragraph?', ['Apply the express money-delivery extension to the next day that is not a Saturday, Sunday, or legal holiday.', 'Treat the contract as automatically void Sunday morning.', 'Move every title, financing, and option deadline by the same number of days.', 'Deliver only to the buyer’s lender because escrow is closed.'], 'The express extension covers paragraph 5’s specified money deliveries. It does not create a universal extension for other contractual clocks or change the named recipient.']);
pair('T01U6', 'resale', 'Paragraph 22 (agreement and changes)',
  ['The buyer requests a lower price during inspection. The seller has not accepted the change. What amount should the performance tracker use?', ['The existing agreed price, while separately recording the proposed reduction as unaccepted.', 'The requested lower price because negotiations began before the option expired.', 'The average of the existing and requested prices.', 'No price until the seller responds, with all deadlines suspended.'], 'Paragraph 22 requires written agreement for a change. A proposal should not be treated as an accepted amendment or as a suspension of the existing agreement.'],
  ['Both sides effectively accept a written amendment changing only closing from December 8 to December 12. What should the agent do?', ['Update closing to December 12 and preserve the other unchanged terms and both document versions.', 'Extend the option automatically by four days.', 'Delete the original contract because the amendment replaces every term.', 'Assume the price changed to the buyer’s last unaccepted proposal.'], 'An accepted amendment changes what it actually addresses. Unchanged terms remain operative; the file must preserve the relationship between the original and the amendment.']);
pair('T01U7', 'resale', 'Paragraph 7F',
  ['An agreed electrical repair is reportedly complete, but the seller supplies no paid invoices or required permit evidence. What should the agent request?', ['The contract’s completion documentation and appropriate technical verification, not just an assurance that work occurred.', 'Only a seller text stating that the buyer waives defects.', 'An agent-created guarantee that the wiring meets every code.', 'Immediate release of the deposit because all incomplete records constitute termination.'], 'Paragraph 7F addresses qualifications, permits, documentation, warranties, completion, and specified remedies. The agent tracks the actual requirements and refers technical/legal conclusions appropriately.'],
  ['An agreed repair is not completed by closing. Paragraph 7F governs and the buyer asks about extra completion time. Which statement accurately identifies the printed option?', ['The buyer may use the specified extension up to five days if necessary for completion, subject to the paragraph’s terms; it is not an unlimited automatic delay.', 'The contract automatically extends thirty days without buyer action.', 'The seller may unilaterally postpone closing until repairs are convenient.', 'Only a photograph is required and incomplete work cannot affect closing.'], 'Paragraph 7F supplies buyer alternatives, including the limited extension. Identify the actual provision and let the principal choose with legal advice as needed.']);
pair('T01U8', 'limitations', '§§ 16.004 and 16.051',
  ['A buyer says a four-year lawsuit limitation lets her ignore a financing notice due tomorrow. Which response is correct?', ['A limitation period for a claim does not extend a contractual financing deadline; they are separate clocks.', 'All purchase conditions remain open for four years.', 'A limitation period begins only after every contract deadline has been waived.', 'The lender chooses the applicable statute of limitations.'], 'Chapter 16 limits specified legal actions. It is not a modification of the parties’ notice conditions, and determining a particular claim’s accrual or tolling requires legal analysis.'],
  ['A former client raises a fraud claim years after closing, but accrual and other material facts are missing. What should the agent do?', ['Preserve the file and refer the limitation analysis promptly to counsel rather than announce a universal four-year result.', 'Tell the client every real-estate claim expires exactly four years after signing.', 'Reopen the expired option because a claim has been mentioned.', 'Discard drafts because the closing date conclusively resolved limitations.'], 'Section 16.004 covers specified claims, and 16.051 is residual. Different claims and accrual rules matter; preserve evidence and avoid an unsupported legal deadline determination.']);
pair('T01U9', 'resale', 'Paragraphs 5B and 18C–E',
  ['A buyer properly exercises a paid, unexpired option. The seller disputes release of earnest money. Which distinction is important?', ['The termination right and the procedure for releasing escrow money are separate matters.', 'Seller consent is always necessary before any option termination is effective.', 'The buyer’s notice itself physically transfers escrow funds.', 'Escrow must follow the buyer agent’s demand without the contract’s procedures.'], 'Paragraph 5B states the option right; paragraph 18 addresses escrow and demands. A disputed release does not convert the two processes into one.'],
  ['A buyer signs a termination notice after the option expired, stating only that another home is preferable. No other basis is supplied. What should the agent flag?', ['The notice form does not create an absent contractual termination right; review the actual basis before asserting entitlement.', 'Any signed termination notice revives an expired option.', 'A reason involving another home is always a financing contingency.', 'The earnest-money amount alone determines whether termination is permitted.'], 'An instrument documenting notice is not an independent source of a right. The actual clause, facts, timing, and delivery must support the action.']);

pair('T02U1', 'occ', '§§ 1101.562 and 1101.563',
  ['A broker will represent a residential buyer and show a home tomorrow. No applicable owner-representative exception is involved. When is the written buyer agreement required?', ['Before the showing; waiting until an offer is prepared is not sufficient when a showing occurs first.', 'Only after the seller accepts an offer.', 'Only when the broker asks the buyer to pay a fee.', 'After closing if the broker was paid by the seller.'], 'Section 1101.563 sets the residential showing/offer timing. The before-offer alternative addresses the situation in which no showing occurs; compensation source does not remove the requirement.'],
  ['A broker uses the limited showing-only route allowed by the statute and will not represent the prospect. Which proposed agreement fits its special limits?', ['A nonexclusive agreement for fourteen days, with the required terms and without services that exceed the limited route.', 'An exclusive six-month agreement labeled showing-only.', 'An oral agreement because no representation exists.', 'A fourteen-day agreement that automatically authorizes offer negotiation without a new appropriate agreement.'], 'Sections 1101.562–.563 distinguish limited showing from representation and limit a showing-only agreement to nonexclusive terms not exceeding fourteen days. Additional brokerage work requires the proper agreement.']);
pair('T02U2', 'rules', '§ 537.11(b), (d) and (e)',
  ['A buyer asks an agent to invent an escalation clause with a custom appraisal remedy. What should the agent do?', ['Explain the drafting boundary and direct the buyer to an attorney for the requested legal language.', 'Draft it and obtain the buyer’s signature so the clause becomes principal-authored.', 'Insert it in special provisions because that space has no drafting restrictions.', 'Copy any internet clause and remove the original author’s name.'], 'Section 537.11 prohibits license-holder drafting or recommending language defining legal rights, obligations, and remedies. A later approval does not turn the agent’s composition into specific written principal instructions.'],
  ['An owner gives the agent specific written instructions to strike identified words in a proposed form. What is the correct distinction under §537.11(d)?', ['The rule treats conspicuous edits specifically instructed in writing by a principal separately from an agent drafting new legal terms; preserve the instructions and seek counsel for legal questions.', 'The instruction permits the agent to add any related remedy the agent considers sensible.', 'The agent must hide the deletions to preserve a clean presentation.', 'A written instruction allows the agent to give a binding legal opinion on the result.'], 'The specific written-direction provision does not remove the legal-advice prohibition or permit undisclosed changes. Follow the actual narrow instruction and the rule’s conspicuous-edit requirement.']);
pair('T02U3', 'occ', '§§ 1101.251–1101.253',
  ['Which description correctly identifies the Broker-Lawyer Committee’s membership structure?', ['Six broker members, six lawyer members, and one public member.', 'Seven brokers and six public members, with no lawyers.', 'Six lawyers appointed by each local real-estate board.', 'Thirteen TREC employees selected by a title company.'], 'The Act establishes a thirteen-member committee composed of six brokers, six lawyers, and a public member, with the specified appointing authorities. It is not a local association drafting committee.'],
  ['A broker says a form becomes mandatory the moment the Broker-Lawyer Committee discusses it. Which correction is best?', ['Committee development and recommendation are distinct from Commission adoption and the operative form rule; verify current adoption and effective status.', 'Discussion makes every draft immediately mandatory statewide.', 'A committee draft is mandatory only for transactions handled by lawyer-brokers.', 'Form effectiveness depends solely on when the broker downloads the file.'], 'The statutory committee assists with forms; Commission authority and the applicable rules govern their adoption and use. A draft, discussion, or download date is not the effective-status determination.']);
pair('T02U4', 'rules', '§ 537.11(a)',
  ['A current mandatory TREC form fits the transaction. The agent prefers a self-written agreement, and no listed exception applies. What is required?', ['Use the applicable mandatory form; personal preference is not an exception.', 'Use the agent’s agreement if it is shorter.', 'Use the old form because its fields are familiar.', 'Use a self-written agreement if both brokers initial it.'], 'Section 537.11(a) requires applicable mandatory forms subject to its specified exceptions. Convenience and broker preference are not among those exceptions.'],
  ['An owner requires a contract prepared by the owner’s attorney. The facts satisfy the express owner/attorney exception. Which conclusion is appropriate?', ['The specified exception can permit that contract, but the license holder still must observe the rule’s legal-advice and drafting limits.', 'The attorney’s involvement authorizes the agent to rewrite its remedies freely.', 'The owner may never require an attorney-prepared contract when a TREC form exists.', 'The agent can omit all required disclosures because the contract is not a TREC form.'], 'The exception concerns form use, not a blanket waiver of disclosure duties or unauthorized-practice restrictions. Read the exception and continuing duties together.']);
pair('T02U5', 'rules', '§§ 531.2 and 535.156',
  ['Three offers differ in price, financing, option periods, and contingencies. What should the seller’s agent do?', ['Present the material terms accurately so the seller can compare and decide, consistent with applicable duties and instructions.', 'Withhold the lowest-priced offer solely because the agent dislikes it.', 'Describe the highest price as guaranteed net proceeds without considering contingencies.', 'Tell every buyer that the seller already accepted before the seller decides.'], 'Fidelity and the offer-handling rule require competent, accurate service to the principal. Material contingencies and costs matter; the agent should not substitute a personal ranking for the seller’s decision.'],
  ['A new written offer arrives while the seller is considering another offer but has not accepted it. The listing agent wants to suppress the new offer because it would require more work. What is the proper response?', ['Handle and communicate the offer under the applicable presentation duties and seller instructions; workload is not authority to suppress it.', 'Wait until the first offer expires even if that defeats the new offer’s deadline.', 'Reject it personally and sign the seller’s initials.', 'Tell the buyer it cannot be considered because any earlier offer creates a contract.'], 'An unaccepted offer does not establish the first sale contract. Apply the actual offer-presentation duty and lawful seller instructions, not the agent’s convenience.']);
pair('T02U6', 'resale', 'Execution provision: effective date is final acceptance',
  ['Seller signs without changes Monday; acceptance is first communicated to buyer’s authorized agent Tuesday. The stipulated facts establish final acceptance Tuesday. Escrow receives the file Wednesday. Which effective date should be recorded?', ['Tuesday, the stipulated final-acceptance date.', 'Monday solely because that is seller’s signature date.', 'Wednesday because escrow receipt always creates the contract.', 'The date scheduled for closing.'], 'The execution provision calls for the final-acceptance date. Signature, communication, escrow receipt, and closing are distinct events; the supplied facts resolve final acceptance here.'],
  ['Seller signs an offer after changing its price. Buyer has not accepted the changed price. Which statement is accurate?', ['The changed response is not unqualified acceptance of the buyer’s offered terms; do not record a completed agreement on those facts.', 'Seller’s signature conclusively accepts the buyer’s original price despite the change.', 'Escrow can choose which price became binding.', 'The counterproposal automatically extends every deadline in the unsigned offer.'], 'A changed material term requires the other side’s agreement. The final-acceptance line should not be completed merely because one side signed a counterproposal.']);

pair('T03U1', 'resale', 'Paragraph 3A–C',
  ['A $384,000 purchase uses $76,800 of buyer savings and $307,200 of conventional financing. Which price entry reconciles?', ['$76,800 cash portion plus $307,200 financed portion equals $384,000 sales price.', '$384,000 cash portion plus $307,200 financing because the lender sends cash at closing.', '$76,800 financing plus $307,200 cash because savings are verified.', '$307,200 total price because the down payment is not part of price.'], 'Paragraph 3 separates cash and financing and sums them to sales price. Loan proceeds are not relabeled buyer cash merely because settlement uses money.'],
  ['Price stays $510,000, but agreed financing is amended from $408,000 to $397,800, with the buyer supplying the difference from savings. What is the revised cash portion?', ['$112,200.', '$102,000.', '$10,200.', '$397,800.'], '$510,000 minus $397,800 is $112,200. The change must be reflected consistently in the accepted contract and lender disclosures, not silently ignored.']);
pair('T03U2', 'resale', 'Paragraph 2B–D',
  ['Seller intends to keep a named attached dining-room chandelier that otherwise falls within the contract’s improvements. What is the appropriate contract treatment?', ['Identify it expressly as an exclusion in paragraph 2D under the parties’ instructions.', 'Assume all seller-owned fixtures are excluded without identification.', 'List it only as a buyer financing cost.', 'Treat the attached fixture automatically as freestanding personal property.'], 'Paragraph 2 defines included improvements/accessories and supplies an exclusion field. Clear instructions and identification avoid a fixture dispute; ownership by seller alone does not exclude an included item.'],
  ['The resale contract includes a permanently installed ceiling fan and states no exclusion. Seller decides after acceptance to take it. What should the agent explain?', ['The existing inclusion controls absent an effective agreed change; seller’s later preference is not itself an exclusion.', 'Seller may remove any item purchased personally before listing.', 'The buyer must pay a second personal-property price for every included fixture.', 'The agent can add an exclusion to the signed file without further agreement.'], 'The accepted property description and exclusions control. An agent should not silently change an executed record or imply that a later unilateral preference amends it.']);
pair('T03U3', 'finance', 'Paragraph 2A and 2B',
  ['Within an agreed buyer-approval period, a buyer cannot obtain approval of income and credit. What does 40-11 require for termination under 2A?', ['Timely notice and the lender’s written statement of the reasons for disapproval, as the paragraph requires.', 'Only a text saying the buyer changed plans.', 'A property-inspection report without lender reasons.', 'No communication because every loan rejection automatically terminates the sale.'], 'Buyer approval concerns the buyer’s available terms and financial qualifications. Paragraph 2A specifies the notice, accompanying lender statement, and deadline; a rejection alone is not automatic termination.'],
  ['Buyer approval has been obtained, but the conventional lender will not approve the property’s insurability. The buyer wants to use 2B and no FHA/VA exception applies. Which requirement matters?', ['Deliver the required notice and lender reasons on or before three days before closing under 2B.', 'Use the expired buyer-approval deadline even though the defect is property approval.', 'Wait until after closing because insurance is never property approval.', 'Submit only the agent’s opinion that financing will fail.'], 'Paragraph 2B separately addresses property approval, including insurability, and has its own notice-and-lender-statement deadline. Do not substitute 2A or an agent opinion.']);
pair('T03U4', 'sellerFinance', 'Paragraphs A and B',
  ['A seller-financing addendum requires credit documents by an agreed date. Buyer fails to deliver them, and seller sends the paragraph B termination notice before the complete documents arrive. Which stated money result accompanies that non-delivery branch?', ['Earnest money is paid to seller under the non-delivery branch.', 'Earnest money is always returned to buyer under both credit-review branches.', 'The seller must extend credit regardless of missing documents.', 'The note automatically changes to a cash purchase.'], 'Paragraph B distinguishes missing timely documents from the seller finding delivered credit unacceptable. In the specified non-delivery termination branch, the earnest money goes to seller.'],
  ['The seller timely finds delivered credit information unacceptable and properly terminates within the applicable paragraph B review period. Which result differs from the non-delivery branch?', ['Earnest money is refunded to buyer under the unacceptable-credit branch.', 'Earnest money is paid to seller as if no documents were ever delivered.', 'The buyer must accept a higher interest rate imposed by seller.', 'The contract continues because seller financing cannot include credit review.'], 'The current addendum provides separate branches and different deposit results. Read the timely review period and actual reason; do not carry the non-delivery result into unacceptable credit.']);
pair('T03U5', 'release', 'Paragraphs A and B',
  ['A seller assuming a VA-related transaction wants both release from loan liability and restoration of VA entitlement. Which approach matches Form 12-3?', ['Address both separate approval subjects and select each applicable closing-consequence choice.', 'Treat release from liability as automatic restoration of entitlement.', 'Use the loan-assumption balance field as proof both approvals occurred.', 'Assume seller’s desire alone binds the lender and VA.'], 'Form 12-3 treats release of liability and restoration of entitlement separately. Each application/approval route and the chosen consequence of nonapproval must be completed.'],
  ['The parties select that missing restoration approval will not delay closing. Restoration is still pending at closing. What should the agent say?', ['The selected no-delay provision matters; pending restoration is not automatically a termination event under the alternative the parties did not select.', 'Either alternative may be used interchangeably after signing.', 'Restoration is deemed approved because closing arrived.', 'The agent should change the selected box to protect seller without buyer agreement.'], 'Read the actual selected alternative. A no-delay selection does not prove approval and cannot be replaced by the different termination alternative through unilateral editing.']);
pair('T03U6', 'assumption', 'Paragraph C',
  ['An assumption purchase is $290,000 with an estimated $176,000 balance and $114,000 cash. The parties select cash adjustment, the actual balance is $173,500, and the variance is within their agreed threshold. What is the adjusted cash amount?', ['$116,500, keeping the $290,000 price unchanged.', '$111,500, because the balance fell.', '$173,500, equal to the debt.', '$287,500, because every variance reduces price.'], 'The selected cash adjustment preserves price: $290,000 minus $173,500 equals $116,500. A lower assumed balance increases cash under that selection.'],
  ['For a $425,000 assumption sale, the parties select price adjustment and hold cash at $160,000. Actual assumed balance is $267,400, within the agreed variance limit. Which figures reconcile?', ['$427,400 price and $160,000 cash.', '$425,000 price and $157,600 cash.', '$422,600 price and $160,000 cash.', '$267,400 price with no cash.'], 'The chosen price-adjustment route produces $160,000 plus $267,400 equals $427,400. Do not apply the alternative cash-adjustment choice.']);

pair('T04U1', 'resale', 'Paragraph 5A(3) (allocation) and 5C (non-delivery)',
  ['Earnest money is $4,800 and option fee $250. Escrow timely receives only $1,000. How is that payment allocated under paragraph 5?', ['$250 first to option fee and $750 to earnest money, leaving an earnest-money shortfall.', '$1,000 only to earnest money, leaving the entire option unpaid.', '$500 to each regardless of the stated amounts.', 'No allocation is possible until seller gives permission.'], 'Paragraph 5 allocates money first to option fee, then earnest money, then additional earnest money. Partial payment does not erase the remaining obligation.'],
  ['The earnest-money deadline passes without full delivery. Before seller sends a termination notice under paragraph 5C, buyer completes delivery. Which fact is decisive for that specified seller termination mechanism?', ['The clause permits seller notice before buyer delivers the earnest money; completed delivery before notice matters.', 'Any initial lateness means automatic termination that delivery cannot affect.', 'Only the option deadline matters for an earnest-money shortfall.', 'Escrow’s receipt automatically proves seller waived every possible remedy.'], 'The specified paragraph 5C termination route uses notice before delivery. State that narrow effect without declaring universal waiver of every other issue.']);
pair('T04U2', 'resale', 'Paragraph 5B (termination option) and 5D (failure to timely deliver option fee)',
  ['A buyer misses timely delivery of the agreed option fee but delivers earnest money. Which consequence is stated for the option?', ['The buyer does not have the unrestricted termination right under the option provision.', 'The entire contract automatically disappears.', 'The earnest money substitutes for an option fee despite the actual allocation and timing facts.', 'The option deadline extends until the fee is paid.'], 'Paragraph 5D states the late-option-fee consequence. It does not say the contract automatically ceases to exist or create an indefinite extension.'],
  ['The buyer lost the unrestricted option through late option-fee delivery but later receives a disclosure that may activate a different contractual termination clause. What should be reviewed?', ['The separate disclosure clause, its facts, and deadline; losing the option does not itself decide every other contractual right.', 'No other termination provision can ever apply after an option-fee failure.', 'The late fee retroactively creates a new option period when the disclosure arrives.', 'Seller must refund every payment without notice.'], 'The option and other specified rights must be analyzed separately. The applicable disclosure provision controls any later right and its own requirements.']);
pair('T04U3', 'resale', 'Paragraph 6B and 6D',
  ['Buyer receives a title commitment Monday, exception documents Wednesday, and the survey Friday. The contract allows five days after receipt of all three for objections, earlier than closing. Which receipt triggers that period?', ['Friday’s receipt of the last required component, subject to the actual earlier-closing limit.', 'Monday because a commitment alone always starts it.', 'Wednesday because surveys are irrelevant to objections.', 'The effective date regardless of document receipt.'], 'Paragraph 6D uses the commitment, exception documents, and survey together for the specified objection period. Record the last required receipt and the earlier-closing limitation.'],
  ['A buyer receives a commitment that requires a lien release before a policy can issue. The agent calls it a guarantee that the property has no title problem. What correction is needed?', ['A commitment states terms and requirements for issuance; the outstanding lien-release requirement still needs resolution.', 'Every listed requirement is automatically waived when the commitment is delivered.', 'A commitment is the deed transferring ownership.', 'The title company’s file replaces the buyer’s opportunity to seek legal title advice.'], 'Paragraph 6 distinguishes the commitment, exceptions, objections, and eventual policy. Receipt of a commitment does not prove requirements have been satisfied or justify a legal title guarantee.']);
pair('T04U4', 'resale', 'Paragraph 6C(1)',
  ['Seller selected the existing-survey route but failed to deliver both the survey and T-47/T-47.1 within the agreed time. Which cost rule applies to the new survey under 6C(1)?', ['Buyer obtains the new survey at seller’s expense under the missing-package provision.', 'The rejection-cost checkbox alone controls even though no complete timely package was delivered.', 'Buyer always pays because the loan is buyer’s loan.', 'No new survey can be obtained once the deadline passes.'], 'Paragraph 6C(1) distinguishes failure to timely furnish the required package from rejection of a timely furnished package. The missing-package branch assigns seller expense.'],
  ['Seller timely delivers the existing survey and declaration. Lender rejects them. The parties selected buyer pays if rejected. Who bears replacement cost under that choice?', ['Buyer, under the selected rejection-cost allocation.', 'Seller automatically because seller prepared the old survey.', 'The surveyor because any old survey is guaranteed acceptable.', 'The listing broker because the buyer selected financing.'], 'A timely complete package reaches the rejection branch, where the selected buyer/seller cost choice matters. Do not substitute the separate failure-to-deliver allocation.']);
pair('T04U5', 'notice', 'Form 58-0: title examination/insurance and district notices',
  ['A transaction has no promulgated TREC sales contract. The agent uses current Notice to Prospective Buyer 58-0 before buyer signs. What is one of its functions?', ['Advise the buyer concerning attorney examination of an abstract or obtaining title insurance; it is not a guarantee of title.', 'Certify that title has no defects because an agent delivered the notice.', 'Replace an executed deed.', 'Create a buyer representation agreement by its delivery alone.'], 'Form 58-0 supplies the stated notice in the described setting, including title advice and district-related warnings. It does not insure title, transfer ownership, or establish representation.'],
  ['A buyer receives 58-0 and asks whether that document means a title policy has already been issued. What should the agent explain?', ['The notice advises about title examination/insurance; actual issuance and coverage require the title process and policy evidence.', 'Delivery itself binds a title insurer to provide complete coverage.', 'The form eliminates all Schedule B exceptions.', 'The notice proves the seller’s deed is legally sufficient.'], 'The notice is advisory, not a policy or legal title opinion. Verify the actual title instruments and refer questions about legal effect appropriately.']);
pair('T04U6', 'resale', 'Paragraph 7A and 7D',
  ['Buyer accepts the property as-is and wants an ordinary inspection during a valid option. What does as-is acceptance mean for inspection?', ['As-is acceptance does not itself prevent inspections or a later agreed amendment; the actual inspection and option provisions still apply.', 'It prohibits every inspection after acceptance.', 'It forces seller to make every repair an inspector suggests.', 'It extends the option until buyer is satisfied.'], 'Paragraph 7D expressly preserves inspections, negotiation of an amendment, and option termination rights despite as-is acceptance. It does not promise repairs or extend deadlines.'],
  ['The buyer’s inspector proposes hydrostatic testing. The contract’s ordinary access provision is in place, but separate seller authorization has not been obtained. What is required?', ['Obtain the seller’s separate written authorization for hydrostatic testing before proceeding.', 'Ordinary inspection access automatically authorizes hydrostatic testing.', 'Buyer’s lender alone can authorize entry and testing.', 'A paid option fee transfers authority to alter any plumbing.'], 'Paragraph 7A treats hydrostatic testing separately and requires seller’s written authorization. General access or a paid option does not replace that permission.']);
pair('T04U7', 'lead', 'Paragraph C(2)',
  ['Under current 56-0, buyer selects the inspection route. Lead is present as determined by the qualifying inspection. Which pair of periods appears in C(2)?', ['Inspection within ten days and the applicable termination notice within fourteen days after the effective date.', 'Inspection and notice both within ten days without distinction.', 'Inspection within fourteen days and notice within thirty days.', 'Inspection at any time and automatic termination upon a report.'], 'Current 56-0 distinguishes the ten-day inspection opportunity from the fourteen-day notice provision when the specified lead presence condition is met. Do not import an older or shorthand single period.'],
  ['A 56-0 buyer timely inspects on day nine, the qualified inspection establishes lead, and notice is delivered on day twelve. Assume all other C(2) requirements are satisfied. Which analysis fits the current form?', ['Day twelve is within the fourteen-day notice period, even though the inspection period is ten days.', 'The notice is necessarily late solely because it is after day ten.', 'The contract automatically terminated on day nine without any notice.', 'The buyer must wait until closing to raise the report.'], 'The two clocks have different functions. On these stipulated facts, inspection occurred in ten days and notice in fourteen; the presence condition and remaining notice requirements are also supplied.']);
pair('T04U8', 'environment', 'Selected investigation provisions and termination paragraph',
  ['The environmental addendum selects a wetlands investigation. A timely qualifying report finds a condition adversely affecting buyer’s intended use. What is required to invoke its termination provision?', ['Deliver the required notice and copy of the qualifying selected report within the agreed period.', 'Send only an agent’s unsupported belief about wetlands.', 'Wait until the option expires because the addendum has no separate period.', 'Treat every unfavorable comment from a neighbor as a qualifying report.'], 'Form 28-2 ties the right to the selected investigation, appropriate professional report, adverse effect on intended use, and timely notice with the report. It is not a general dissatisfaction option.'],
  ['Only the endangered-species investigation is selected. Buyer produces an unrelated cosmetic inspection and asks to terminate under 28-2. Which issue should be flagged?', ['The supplied report does not establish the selected investigation’s qualifying condition or supporting report requirement.', 'Any inspection report automatically activates every selected and unselected assessment.', 'Cosmetic defects are conclusively an endangered-species condition.', 'The form always refunds earnest money on a bare request, regardless of basis.'], 'The selected categories and specified report requirements govern. An unrelated inspection is not evidence of the selected environmental condition.']);
pair('T04U9', 'resale', 'Paragraph 7H',
  ['Seller agrees to reimburse up to $700 toward an optional residential service contract. Buyer purchases a qualifying plan costing $640. What amount does the cap alone support?', ['$640, the actual cost within the $700 limit.', '$700 regardless of actual cost.', '$1,340 because the cap is added to plan cost.', 'No reimbursement because a service plan is optional.'], 'Paragraph 7H limits the reimbursement to the agreed amount toward cost. A cap is not a flat extra payment; optional purchase and an agreed reimbursement are compatible.'],
  ['A buyer’s chosen service plan costs $825 and the agreed seller cap is $600. No other contribution applies. What remains for buyer?', ['$225, subject to the actual plan and closing accounting.', '$600 because that is the cap.', '$825 because seller never contributes to optional plans.', 'Nothing because a cap requires unlimited reimbursement.'], '$825 less the $600 cap leaves $225. The contract does not guarantee what a particular plan covers; cost allocation and coverage review are different tasks.']);

pair('T05U1', 'resale', 'Paragraph 10A–B',
  ['The possession choice is closing and funding. Papers are signed, but escrow confirms funding is pending. What should the agent do with keys?', ['Follow the agreed closing-and-funding trigger; do not treat signatures alone as authority to deliver possession.', 'Deliver keys because the buyer signed a note.', 'Deliver keys only because earnest money was previously paid.', 'Let the seller’s mover decide whether possession occurred.'], 'Paragraph 10 distinguishes closing and funding from other events and offers a different lease-based route when selected. Follow the actual choice and verified facts.'],
  ['At possession, seller hands over physical keys but remains connected to the property’s smart locks and security devices. What still needs attention?', ['Provide the agreed access information and remove seller’s personal connections as paragraph 10B requires.', 'Nothing, because smart-device access is unrelated to possession.', 'Buyer must accept seller’s ongoing remote access until the title policy arrives.', 'The listing agent should publish passwords so all parties can retrieve them.'], 'Paragraph 10B addresses access devices and codes and removal of seller’s access/connections. Handle credentials securely; handing over physical keys alone is incomplete.']);
pair('T05U2', 'rules', '§ 537.11(b)(3)–(5) and (d)',
  ['A buyer asks an agent to write a new right to cancel if resale value falls. The agent proposes placing it in paragraph 11. What is wrong?', ['Special provisions is not authority for an agent to draft a new legal right; the requested language needs appropriate legal drafting.', 'The clause is allowed whenever it is fewer than fifty words.', 'Every buyer request is automatically a specific written legal clause authored by the buyer.', 'The heading special provisions makes all inserted terms merely informational.'], 'The rule prohibits agent-drafted rights, obligations, or remedies. The location in the form does not change the substance or turn legal drafting into informational completion.'],
  ['The parties need a currently available promulgated addendum for a stated condition. The agent wants to summarize its remedy in special provisions instead. Which rule applies?', ['Do not substitute an informational provision for a promulgated form that addresses the matter; use the applicable form under the rule.', 'A shorter summary always overrides the mandatory form requirement.', 'The agent may omit the addendum if its title appears in an email.', 'The special-provisions summary has priority because it is typed.'], 'Section 537.11 prohibits the identified substitution. A summary can omit protections or alter effects; form completion and legal drafting remain distinct.']);
pair('T05U3', 'sellerLease', 'Paragraphs 1, 3 and 4; form use limitation',
  ['A seller remains in the home for twenty days after closing under 15-7. Who is landlord and who is tenant?', ['Buyer is landlord; seller is tenant.', 'Seller remains landlord until moving out; buyer is tenant.', 'Both are buyers because the sale closed.', 'The listing broker becomes landlord by holding the keys.'], 'The seller’s temporary lease covers seller occupancy after closing, with buyer as landlord and seller as tenant. The current form is for no more than ninety days after closing.'],
  ['Under the seller’s temporary lease, closing and funding occur May 4 and occupancy ends May 9. Rent is $110 per day; the closing/funding day is excluded and no holdover occurs. What is the regular rent?', ['$550 for May 5 through May 9.', '$660 because May 4 must be charged too.', '$110 because only the last day is charged.', '$990 because the form always charges a minimum of nine days.'], 'Paragraph 4 excludes the day of closing and funding. Five chargeable days at $110 equal $550 under the supplied term. Read the actual dates and separate any holdover period.']);
pair('T05U4', 'resale', 'Paragraph 12A(1)(b) and 12B',
  ['Seller’s ordinary buyer-expense cap is $3,200. A separate paragraph 12B seller contribution toward buyer brokerage is $6,000. Buyer’s broker fee is $7,500. Can the ordinary expense cap automatically cover the $1,500 fee gap?', ['No. The ordinary expense provision excludes brokerage compensation/contributions; separate obligations and contribution fields must be respected.', 'Yes, every unused seller cap automatically pays any brokerage gap.', 'Yes, if the buyer’s agent writes the fee in the tax-proration line.', 'No, because seller can never contribute toward buyer brokerage.'], 'Current 20-19 separates ordinary expenses from paragraph 12B brokerage contributions. The separate compensation agreement and selected contribution control; do not blend the buckets.'],
  ['Buyer owes a broker $9,000 under a separate agreement. Seller agrees in 12B to contribute $7,200. No other fee arrangement applies. What remains the buyer’s obligation?', ['$1,800, without treating the contribution as an amendment of the separate fee agreement.', '$7,200 because seller’s contribution becomes buyer’s fee.', '$9,000 plus $7,200 because contributions are surcharges.', 'Nothing, because any seller contribution cancels the buyer agreement.'], '$9,000 minus $7,200 leaves $1,800. Paragraph 12B’s contribution does not itself alter the separate written compensation obligation.']);
pair('T05U5', 'resale', 'Paragraphs 13 and 14',
  ['Taxes were prorated using an estimate at closing. The actual bill later requires an adjustment under paragraph 13. What should the parties’ file reflect?', ['The surviving adjustment obligation and a reconciliation using the actual bill.', 'Closing automatically cancels every tax adjustment.', 'Only the buyer may request a favorable adjustment, regardless of allocation.', 'The agent may change the original settlement statement without a transparent record.'], 'Paragraph 13 provides adjustment when actual taxes differ and survives closing. Preserve the original estimate and document the actual reconciliation.'],
  ['A covered casualty occurs before closing and seller cannot restore by closing because of factors beyond seller’s control. Which response reflects paragraph 14?', ['Review the buyer’s stated alternatives, including termination, the specified extension, or accepting damaged property with the specified insurance-related terms.', 'The agent must force buyer to accept the damage at the full price without alternatives.', 'Every casualty automatically requires seller to reduce price by the buyer’s estimate.', 'The contract always extends indefinitely until an insurer pays.'], 'Paragraph 14 provides specific alternatives and conditions, including a limited extension and an acceptance route involving insurance proceeds/consent and deductible credit. It is not an unlimited extension or automatic price rewrite.']);
pair('T05U6', 'resale', 'Paragraph 18C and 18E',
  ['Escrow sends one party’s earnest-money demand to the other party. Escrow receives a timely written objection within the paragraph 18 period. What should the agent avoid claiming?', ['That the no-objection disbursement route applies despite the timely received objection.', 'That the objection and its receipt should be preserved.', 'That disputed entitlement may require legal review.', 'That the contract’s actual release procedure should be examined.'], 'The demand procedure distinguishes timely objection from no objection. Paragraph 18E makes an objection effective on escrow’s receipt. An agent should not promise a disputed disbursement.'],
  ['The objecting party drafts an objection before the deadline but escrow receives it after the required period. What delivery fact matters under 18E?', ['Receipt by escrow, not merely the date the objection was drafted.', 'The computer file creation time alone.', 'The date the party first became dissatisfied.', 'Only the buyer agent’s private knowledge of the objection.'], 'Paragraph 18E expressly uses receipt for notices of objection under that provision. Do not replace it with a different notice rule or undocumented intention.']);
pair('T05U7', 'resale', 'Paragraphs 19 and 21',
  ['A seller assumes representations disappear at closing because the deed was delivered. What does paragraph 19 require the agent to flag?', ['The contract provides that covenants, representations, and warranties survive closing; do not announce universal extinguishment.', 'Every representation expires when earnest money is delivered.', 'Only statements typed in special provisions can survive.', 'The broker can decide which representations remain by deleting archived pages.'], 'Paragraph 19 states survival and addresses accuracy of seller representations. Legal disputes about a particular obligation still belong with counsel.'],
  ['A party sends a contractual notice using an address copied from an old offer, rather than the accepted contract’s notice information. What is the appropriate review?', ['Compare the actual paragraph 21 notice terms, selected contacts, method, and delivery evidence; do not assume the old address suffices.', 'Any address ever used by the party automatically meets every notice condition.', 'No written notice can be sent electronically under the form.', 'Changing a contact in the agent’s private notes amends the accepted notice provision.'], 'Paragraph 21 governs the specified written notice methods and contacts. Evidence of the agreed information and actual delivery matters; an old draft or private note is not conclusive.']);
pair('T05U8', 'resale', 'Paragraph 22 and broker-information page instructions',
  ['A proposed 20-19 packet checks a financing attachment box but omits the financing addendum itself. What should the agent do before presentation?', ['Obtain and verify the actual completed attachment; a checked box is not a substitute for its missing terms.', 'Assume the standard financing terms are supplied automatically.', 'Let escrow invent the missing interest-rate and approval terms after acceptance.', 'Remove all references to financing without buyer instructions.'], 'Paragraph 22 identifies attachments made part of the agreement. A complete package must contain the actual applicable terms; the agent should not infer missing negotiated choices.'],
  ['On current 20-19’s broker-information page, an agent is about to sign where the form instructs brokers to print names and not sign. What is correct?', ['Follow the current page’s print-name/do-not-sign instructions and keep party execution distinct.', 'Sign anyway because every broker-contact field is a compensation contract.', 'Copy instructions from the farm-and-ranch fee page without reading 20-19.', 'Omit the buyer and seller signatures because broker identification replaces them.'], 'Current 20-19 identifies the broker contacts and expressly directs printed names rather than signatures there. Different forms’ broker/fee structures must not be conflated.']);
pair('T05U9', 'resale', 'Paragraphs 3, 5A, 12 and 13',
  ['For a simplified closing, price cash is $72,000; credited earnest/option money totals $4,250; uncovered buyer expenses are $2,100; seller tax credit is $1,900. No other figures apply. What purchase cash is due?', ['$67,950.', '$76,050.', '$70,050.', '$63,850.'], '$72,000 − $4,250 + $2,100 − $1,900 = $67,950. Separate credits from charges and do not count deposits twice.'],
  ['Price cash is $98,000. Credits are earnest $6,000, option $300, and seller tax proration $2,200. Buyer’s uncovered ordinary expenses are $3,400 and uncovered brokerage fee $1,600. No other adjustments apply. What cash is due?', ['$94,500.', '$92,900.', '$101,100.', '$89,500.'], '$98,000 − $6,000 − $300 − $2,200 + $3,400 + $1,600 = $94,500. Brokerage and ordinary expenses are distinct charges but both remaining buyer obligations enter this simplified cash reconciliation.']);

pair('T06U1', 'rules', '§ 537.11(a); current mandatory form selection',
  ['A detached-looking residence is legally a condominium unit. Which fact should guide contract selection?', ['The legal ownership regime and actual transaction facts, not appearance alone.', 'A detached roof automatically requires the one-to-four resale form.', 'The marketing phrase townhome conclusively determines ownership.', 'Any contract works if the listing price is correct.'], 'Mandatory form selection must fit the transaction. Legal condominium ownership can exist despite detached appearance; verify the property and form scope.'],
  ['An agent selects a contract from an old folder without checking whether construction is complete or the home has ever been occupied. What is the defect in the process?', ['Material scope facts and the current applicable form have not been verified.', 'The form’s filename is sufficient evidence of applicability.', 'All residential contracts impose identical construction duties.', 'Only the mortgage amount determines which home contract applies.'], 'Current applicability depends on facts such as ownership, construction, and occupancy, not merely a familiar filename. Verify scope before completing fields.']);
pair('T06U2', 'condo', 'Paragraph 2B–D and 6C',
  ['An agent imports resale paragraph numbers and a subdivision association review period into a condominium checklist. What must be corrected?', ['Use the condominium form’s own document, certificate, refusal-right, and objection provisions rather than transplanted numbers and periods.', 'Keep the copied periods because all TREC property forms have identical timing.', 'Delete every condominium document requirement because the seller has a survey.', 'Use whichever period gives the agent the fewest tasks.'], 'The condo form has distinct paragraph 2 document/certificate mechanisms and its own objection structure. Similar subject matter does not justify copying another form’s clause numbers or periods.'],
  ['A condo resale file includes both declaration/bylaws/rules and a resale certificate. The agent marks receipt of one as receipt of both. Why is that unreliable?', ['The form treats the documents and certificate as separate required items with their own receipt records and conditions.', 'A resale certificate always contains the full declaration and rules by definition.', 'Neither item matters if the unit is furnished.', 'Receipt can be assumed from the seller’s statement that the association is organized.'], 'Paragraph 2B and 2C distinguish governing documents from the resale certificate. Maintain evidence for each rather than deeming one delivered from the other.']);
pair('T06U3', 'condo', 'Paragraph 2C',
  ['A condo resale certificate is four months old when supplied. Which issue must the buyer’s agent flag under the current form?', ['The stated certificate age requirement is no more than three months; obtain an appropriate current certificate or address the actual selected provision.', 'Any certificate less than one year old necessarily complies.', 'The survey’s date controls the certificate’s age.', 'An old certificate automatically converts the property into a subdivision sale.'], 'Paragraph 2C specifies a certificate prepared no more than three months before delivery. The actual receipt selection and any applicable statutory rights still require review.'],
  ['The selected condo provision requires delivery of the certificate, and buyer receives it after signing. Which period should the agent consult for the form’s postreceipt termination mechanism?', ['The condo provision’s seven-day period, subject to its actual conditions and preserved statutory rights.', 'The subdivision association addendum’s three-day period automatically.', 'A universal ten-day option created by receiving any association record.', 'No period because all post-signing certificates are deemed approved.'], 'The condominium contract’s mechanism differs from the subdivision association addendum. Apply the actual seven-day language, delivery facts, selected route, and retained statutory rights.']);
pair('T06U4', 'farm', 'Paragraph 3D',
  ['A farm contract selects a $7,500-per-acre price adjustment from 80 represented acres. The survey shows 82 acres, and no threshold issue affects the result. What is the price change?', ['$15,000 increase, allocated as the selected form option directs.', '$15,000 decrease because the survey is newer.', '$615,000 increase in addition to the represented total.', 'No adjustment because acreage is always informational.'], 'Two additional acres at $7,500 equal $15,000. Paragraph 3D’s selected adjustment and allocation control; do not confuse total surveyed value with the change.'],
  ['Under a selected farm acreage-adjustment clause, the price change exceeds ten percent. What should the agent review before treating the new price as unconditionally binding?', ['The paragraph 3D termination election and its agreed notice period after survey receipt.', 'Only the original option deadline because acreage has no separate provision.', 'A mandatory seller-only right to ignore the survey.', 'A universal rule that the contract automatically terminates without notice.'], 'Paragraph 3D supplies a particular threshold and election mechanism for a price change exceeding ten percent. Read the actual selected fields and timely election rather than assuming automatic cancellation.']);
pair('T06U5', 'lot', 'Form scope and paragraph 7',
  ['A marketed vacant lot is intended for a one-to-four-family residence, but water and sewer availability have not been verified. What should the buyer’s agent do?', ['Use the applicable scope analysis and verify utilities and suitability rather than treating the vacant-lot label as a guarantee.', 'Assume residential zoning guarantees immediate utility connections at no cost.', 'Use a completed-new-home contract because the buyer plans to build later.', 'State that vacant property cannot have title or use restrictions.'], 'The unimproved form’s scope and condition provisions require attention to actual property suitability and utilities. A marketing label or intended future construction is not proof of present availability.'],
  ['A utility provider reports that a line passes nearby but service to the lot requires a separate availability review. What is the accurate buyer report?', ['Nearby infrastructure does not establish an approved connection; obtain the provider’s actual service and cost information.', 'The lot already has guaranteed service because a line is visible.', 'The seller must pay any future connection cost regardless of the contract.', 'A survey alone is an unconditional utility-service commitment.'], 'Paragraph 7 directs buyer attention to whether utilities are available and adequate for intended use. Distinguish observed infrastructure from the provider’s actual commitment.']);
pair('T06U6', 'incomplete', 'Form warning and paragraph 7B–D',
  ['Buyer will close and fund before the new home is complete. Is 23-20 appropriate simply because its title says incomplete construction?', ['No. Its scope warning excludes a transaction in which closing occurs before completion; obtain appropriate authorized guidance and documentation.', 'Yes, the title authorizes every construction-stage closing.', 'Yes, if the agent deletes the warning without discussing it.', 'No, because 23-20 is only for previously occupied homes.'], 'The form’s express warning matters more than a casual reading of its title. It is not intended for closing before completion or condominium transactions.'],
  ['The parties agree to upgrade flooring during a 23-20 transaction. What is the proper treatment?', ['Use the required written change-order process and reconcile the agreed price/payment effects under paragraph 7.', 'Let the agent verbally approve the upgrade and adjust price after closing.', 'Treat every upgrade as free because the base plan was attached.', 'Remove the construction documents because a new selection cancels them all.'], 'Paragraph 7 incorporates construction documents and addresses written change orders, selection timing, and cost adjustments. A change must be consistently documented, not silently added.']);
pair('T06U7', 'farm', 'Paragraphs 2 and 4 (crops and leases)',
  ['A farm workshop file contains an existing hunting lease. The agent copies a resale checklist listing no leases because the property is not a rental house. What is wrong?', ['The farm form’s surface-lease review includes uses such as hunting; the existing lease must be identified and handled under the actual contract.', 'Only residential leases ever matter in a land sale.', 'The hunting lease disappears merely because seller signs a sales contract.', 'A mineral reservation automatically accounts for every surface lease.'], 'The farm form distinguishes surface leases and natural-resource interests. A nonresidential use is not a reason to omit an existing lease.'],
  ['Under the farm form’s unmodified crop provision, seller has growing crops and possession has not yet passed. Which point must the workshop tracker reflect?', ['Seller’s stated right to harvest before possession, while separately reviewing any agreed changes and lease obligations.', 'Buyer automatically owns every growing crop from the first offer signature.', 'Harvest rights always continue indefinitely after possession.', 'The agent may add a crop reservation after acceptance without agreement.'], 'The farm property provision addresses growing crops and harvest through delivery of possession. Apply the actual term and any accepted changes rather than borrowing a residential fixture assumption.']);

pair('T07U1', 'sale', 'Paragraphs B and C',
  ['A seller’s notice says another offer was accepted but does not require the buyer to waive the sale-of-other-property contingency. What is missing for the paragraph B mechanism?', ['The notice must include the required waiver demand, not just the fact of accepting another offer.', 'The notice must set a new brokerage fee.', 'No missing term matters because any mention of another offer automatically waives the contingency.', 'The buyer’s current home must first be deeded to the seller.'], 'Paragraph B describes both acceptance of another offer and a notice requiring waiver. Read the trigger as written rather than treating a partial message as complete.'],
  ['After a proper paragraph B notice, buyer sends a timely written waiver but omits the additional earnest money required by paragraph C. What should the agent flag?', ['Waiver requires both written notice and the additional earnest money under the selected terms; a notice alone is incomplete.', 'Additional earnest money is only a suggested amount.', 'Any later delivery is necessarily timely because buyer sent a message.', 'The original option fee automatically satisfies all additional earnest money.'], 'Paragraph C specifies the components of waiver. Review timely completion of both rather than deeming the condition waived from the message alone.']);
pair('T07U2', 'backup', 'Paragraphs A and H',
  ['Buyer and seller execute a backup contract while the first contract remains in place. What happens to initial earnest money and option obligations?', ['They are governed by the original effective date and paragraph 5; they are not postponed merely because performance is otherwise contingent.', 'All money is automatically deferred until the first contract terminates.', 'The backup is not binding until the primary buyer closes.', 'The seller may spend the backup buyer’s deposit without escrow.'], 'Current 11-9 is binding on execution and expressly retains initial money duties while specified performance is contingent. Original and amended effective dates have different functions.'],
  ['The first contract terminates on June 6. Seller delivers the required termination notice to backup buyer on June 8. What is the amended effective date under paragraph H?', ['June 8, when seller delivers the required notice to buyer.', 'June 6 automatically, regardless of notice.', 'The backup’s original signature date for every purpose.', 'The date seller verbally considered terminating the first contract.'], 'Paragraph H ties the amended effective date to seller’s delivery of notice to buyer. Record the actual delivery event, not merely the first contract’s termination date.']);
pair('T07U3', 'minerals', 'Paragraphs A–C',
  ['Seller owns half of the mineral estate and reserves one-half of seller’s owned interest under the addendum. What fraction of the entire mineral estate is reserved by this seller?', ['One-quarter, before considering any separate title issues.', 'One-half, because the selected fraction always refers to the whole estate.', 'All minerals, because any reservation prevents a conveyance.', 'Three-quarters, because buyer’s fraction is added to seller’s.'], 'The reservation is a fraction of seller’s owned interest. One-half of one-half equals one-quarter; verify ownership rather than assuming seller owns the entire estate.'],
  ['Seller waives surface rights in the reservation addendum. A preexisting mineral owner who is not a party holds separate rights. What should the agent explain?', ['The seller’s waiver does not itself extinguish nonparties’ rights; title and legal review remain necessary.', 'The checkbox eliminates every mineral owner’s surface rights automatically.', 'The buyer can ignore recorded leases because seller signed.', 'Water rights are necessarily reserved by the mineral definition.'], 'The form distinguishes the parties’ choices from nonparty interests and excludes specified substances, including water, from its mineral definition. A seller cannot simply waive another owner’s rights.']);
pair('T07U4', 'resale', 'Paragraphs 5B and 21',
  ['A buyer directs timely option termination and the notice identifies the correct contract, but the agent has not checked the accepted notice contacts. What should happen before relying on delivery?', ['Verify the applicable notice provision, recipient details, method, and evidence before declaring the notice effective.', 'Send it to any address found on an old listing and assume delivery.', 'Wait for seller to consent because all option notices require mutual signatures.', 'Treat the form’s filename as proof of timely delivery.'], 'A valid basis and a correctly labeled form do not replace the actual notice requirements. Paragraphs 5 and 21 must be applied with the contract and delivery record.'],
  ['An agent prepares a buyer termination notice naming the wrong property while the option deadline approaches. What is the proper response?', ['Correct the contract identification and verify timely compliant delivery; do not rely on an erroneous draft as completion.', 'Leave the wrong property because buyer’s signature cures every identification error.', 'Backdate the corrected notice after the period expires.', 'Send only an escrow release because it always substitutes for a termination notice.'], 'Accurate identification, authorized basis, and timely notice are different necessary quality checks. A release is not a universal substitute for termination notice, and backdating is not evidence of timely action.']);
pair('T07U5', 'resale', 'Paragraphs 18C and 22',
  ['Both parties discuss ending the sale but have not agreed who receives the earnest money. What should the agent avoid saying?', ['That the discussion alone settles both mutual termination and deposit distribution.', 'That the unresolved money issue should be identified clearly.', 'That an appropriate authorized written agreement may be needed.', 'That escrow instructions must be reviewed separately.'], 'Mutual agreement, the written record, and escrow disposition must be established rather than assumed. The agent should not compose a legal settlement or promise a distribution from an incomplete discussion.'],
  ['Seller alone signs a proposed mutual termination releasing all earnest money to seller. Buyer has not agreed. Which characterization is accurate?', ['It is a proposal, not established mutual assent to termination and that distribution.', 'It binds buyer because seller owns the property.', 'The word mutual substitutes for the missing buyer agreement.', 'Escrow must distribute immediately because one signature appears.'], 'A label does not supply another party’s agreement. Paragraphs 18 and 22 require attention to the actual written agreement and escrow process.']);
pair('T07U6', 'coastal', '§ 33.135(a)–(b)',
  ['A parcel’s actual location may trigger the coastal-area statutory notice. The agent knows only that it has a coastal-city mailing address. What is the sound approach?', ['Verify the legally relevant location and statutory trigger, then use the applicable notice; a mailing label alone is insufficient.', 'Assume every property in any coastal county has the same notice trigger.', 'Omit notice whenever the buyer does not plan to swim.', 'Replace the notice with the seller’s statement that erosion has never occurred.'], 'Section 33.135 defines the notice obligation by the specified property relationship, not a casual marketing or mailing description. Verify the actual statutory location and read the complete notice.'],
  ['A buyer says a coastal notice guarantees a permanent shoreline and permits all future building. How should the agent correct that?', ['The notice warns of coastal-property risks and legal limits; it is not a guarantee of boundaries or development permission.', 'Delivery creates a state guarantee against erosion.', 'Signing the notice overrides all permitting requirements.', 'The notice transfers any state-owned submerged land to buyer.'], 'The statutory notice warns about changing coastal boundaries, state interests, and regulatory issues. Its delivery does not insure a shoreline or confer permits or state land.']);
pair('T07U7', 'hoa', 'Paragraphs A(1) and C',
  ['Under association addendum 36-11 A1, seller must deliver subdivision information. Buyer receives it after contracting. Which review period should be tracked?', ['The actual three-day postreceipt period, subject to the earlier-closing limit and other A1 terms.', 'The condo contract’s seven-day period automatically.', 'A new unrestricted thirty-day option.', 'No review period because an association is private.'], 'The subdivision association addendum is not the condominium form. Its A1 delivery and termination terms, including the three-day mechanism and earlier-closing limit, control.'],
  ['Paragraph C transfer charges total $1,150. Buyer’s selected C cap is $800. Regular dues and prorations are separate. What is the C allocation?', ['Buyer $800 and seller $350.', 'Buyer $1,150 and seller zero because every association expense belongs to buyer.', 'Seller $1,150 and buyer zero because the cap is a seller allowance.', 'Buyer $350 and seller $800.'], 'Paragraph C assigns the selected buyer amount and seller excess for the defined charges. Do not mix regular dues, prorations, or separately treated document costs into that calculation.']);
pair('T07U8', 'short', 'Paragraphs A, D and I',
  ['A short-sale lender letter permits sale and releases its lien but expressly preserves the seller’s unpaid personal debt. Why does the agent need further review?', ['The addendum seeks the specified full satisfaction of seller liability as well as release; permission to sell and a lien release alone may not satisfy it.', 'Any letter from one lender automatically satisfies every lienholder and debt condition.', 'A short sale always leaves seller liable, regardless of the selected contract.', 'The buyer’s earnest money is automatically paid to the lender on receipt of the letter.'], 'Paragraph A’s stated approval includes liability satisfaction and a recordable lien release; paragraph I applies the obligations to each lienholder. Read what the letter actually approves and route legal questions to counsel.'],
  ['Two lienholders must consent to a short sale. Only the first has issued the required approval by the agreed deadline. What should the agent flag?', ['The necessary approval from each lienholder has not been established; apply the addendum’s actual deadline/consequence rather than treating one consent as sufficient.', 'One approval automatically binds the junior lienholder.', 'The listing broker can release the junior lien personally.', 'The deadline moves indefinitely whenever any lender responds.'], 'The addendum applies to each lienholder and contains a specified approval notice deadline and consequence. Do not invent a universal extension or assume one creditor speaks for another.']);
pair('T07U9', 'occ', '§ 1101.558 (brokerage disclosures) and § 1101.563 (written buyer agreement)',
  ['A prospect receives IABS, but no representation agreement or other agency-creating facts are supplied. What should the agent avoid claiming?', ['That delivery of the informational notice by itself creates the required buyer representation agreement.', 'That the notice explains brokerage relationships.', 'That the written agreement requirement needs separate attention.', 'That actual agency status should be disclosed accurately.'], 'The statute separates brokerage disclosure information from the written agreement governing services. Do not confuse giving a notice with establishing the separate contract.'],
  ['A buyer signs a representation agreement and the broker concludes there is never any reason to provide IABS. What is the flaw?', ['Agreement and informational disclosure are separate duties; evaluate and satisfy the actual disclosure requirement and any statutory exception.', 'Every agreement legally prohibits providing an informational notice.', 'A compensation provision automatically contains all required statutory information.', 'IABS is needed only after the deed is recorded.'], 'The existence of an agreement does not itself establish that the separate statutory information requirement was satisfied or an exception applies. Read the duties distinctly.']);
pair('T07U10', 'rules', '§§ 537.1 and 537.64 (voluntary Non-Realty Items Addendum)',
  ['The current Non-Realty Items Addendum 57-0 is classified for voluntary use. What does voluntary mean in this context?', ['Its use is not mandated in the same way as an applicable mandatory form, but the transaction’s personal-property terms and other legal duties still need accurate documentation.', 'Personal-property facts may be concealed from the lender.', 'The agent may freely draft any legal warranty because the form is voluntary.', 'The form automatically transfers real-property title.'], 'The current form classification distinguishes voluntary from mandatory use. It does not remove disclosure, accuracy, authorized-drafting, or lender requirements.'],
  ['A freestanding refrigerator will be purchased separately for $1,100. The agent proposes hiding that payment in the house’s down payment because the non-realty addendum is voluntary. Which response is correct?', ['Document and disclose the separate personal-property arrangement accurately; voluntary form status is not permission to misstate the financing or consideration.', 'Agree, because a voluntary form means the underlying facts are optional.', 'Treat the refrigerator as real-property collateral without lender review.', 'Add $1,100 to earnest money and omit the personal-property agreement.'], 'Voluntary status concerns form use, not permission to conceal or mischaracterize facts. Keep the separate consideration and financing disclosures consistent.']);
pair('T07U11', 'backup', 'Paragraphs H and I',
  ['The first buyer and seller amend their primary contract’s closing date. The backup buyer claims that amendment makes the backup primary. Which conclusion matches 11-9?', ['An amendment of the first contract is not itself its termination, so it does not by itself activate the backup.', 'Every amendment automatically terminates the first contract.', 'The backup agent can declare an amended effective date whenever primary terms change.', 'Changing primary closing automatically waives the backup’s money duties.'], 'Paragraph I distinguishes amendment of the first contract from termination, while H addresses the required notice and amended effective date. Do not substitute a change for termination.'],
  ['The first contract truly terminates, but no required seller notice has yet been delivered to backup buyer. What should the workshop log show?', ['Termination evidence and a pending seller-notice task; do not invent the amended effective date from private knowledge alone.', 'All backup deadlines necessarily began when an agent heard a rumor.', 'The backup automatically expired because notice was not simultaneous.', 'The title company alone can select any convenient effective date.'], 'Paragraph H uses seller’s delivery of notice. Record the actual events and complete the required notice rather than backfilling a convenient date.']);

pair('T08U1', 'occ', '§ 1101.652(b)(3)–(4)',
  ['An agent learns a seller’s defect statement is materially false and proposes leaving it unchanged to avoid losing the deal. What is the proper course?', ['Do not participate in misrepresentation or concealment; document the facts and promptly involve the supervising broker and appropriate disclosure/legal process.', 'Keep the false statement because seller signed it.', 'Wait until after closing, when the buyer can sue instead.', 'Replace the statement with an agent guarantee that no defect exists.'], 'The Act’s disciplinary grounds include material misrepresentation and specified nondisclosure conduct. A seller signature does not license an agent to knowingly perpetuate a false material record.'],
  ['A loan package labels borrowed down-payment funds as buyer savings to improve approval odds. The agent notices the discrepancy. What should the agent do?', ['Stop participating in the false characterization, preserve the facts, and route an accurate correction through the broker and lender.', 'Approve the label if the buyer promises to repay the separate loan.', 'Move the borrowing detail to a private note the lender will never see.', 'Assume misrepresentation is allowed whenever no one has lost money yet.'], 'Material accuracy is required; expected approval or an absence of a completed loss is not permission to falsify the transaction’s funding facts.']);
pair('T08U2', 'occ', '§ 1101.563 (agreement compensation and negotiability)',
  ['A residential buyer agreement identifies an objectively ascertainable negotiated compensation method. The agent later says an industry-wide mandatory percentage overrides it. Which correction is appropriate?', ['Compensation is negotiable and governed by the actual lawful agreement; do not invent an industry-mandated rate.', 'Every broker must charge the same statewide percentage.', 'A seller contribution automatically replaces all buyer-agreement compensation terms.', 'The agent may insert any desired percentage after the buyer signs.'], 'Section 1101.563 requires the compensation method and negotiability disclosure. No industry-wide rate is supplied by the statute. The actual agreement and any effective changes matter.'],
  ['Buyer’s written agreement sets a $7,800 fee. Seller offers a $5,300 contribution, with no agreement changing the fee. What fact should the agent communicate?', ['The offered contribution is not itself a change to the $7,800 obligation; reconcile the $2,500 difference with the actual agreements.', 'The fee is automatically reduced to $5,300.', 'The fee automatically increases to $13,100.', 'The contribution permits the agent to omit disclosure of compensation.'], 'An outside contribution and the agreed compensation are distinct. The arithmetic difference is $2,500; do not imply a separate payer’s offer amends the buyer’s agreement.']);
pair('T08U3', 'rules', '§ 531.19(a)',
  ['A seller instructs the agent to reject buyers of a stated national origin. What should the agent do?', ['Refuse to carry out the discriminatory instruction and involve the broker in lawful transaction handling.', 'Follow it because loyalty to the seller overrides fair-housing duties.', 'Avoid writing the instruction down but apply it orally.', 'Use the buyer’s surname as a substitute so the rejection is not explicit.'], 'Section 531.19 forbids the discriminatory conduct and reaches inquiries, responses, facilitation, and preferences. Loyalty does not authorize unlawful discrimination or proxy screening.'],
  ['A buyer asks the agent to identify which applicants belong to a protected religion so offers can be screened. What does §531.19 require?', ['Do not facilitate the prohibited inquiry or religious screening; redirect to lawful transaction criteria.', 'Provide the information if it is already public.', 'Rank applicants by religion only in private notes.', 'Ask the listing agent to do the screening so responsibility transfers.'], 'The rule reaches responding to or facilitating the inquiry, not just an explicit discriminatory advertisement. Delegating or privatizing the conduct does not make it permissible.']);
pair('T08U4', 'occ', '§§ 1101.556 and 1101.651(d)',
  ['An intermediary learns the seller would accept less than the asking price. No separate written authorization or applicable exception permits disclosure. What should occur?', ['Keep the confidential negotiating limit within the statutory restriction.', 'Tell buyer because paying a commission buys access to every seller fact.', 'Disclose it if the agent thinks the lower price is fair.', 'Include it in the seller’s property-condition notice.'], 'Section 1101.651(d) separately protects seller minimum and buyer maximum price information absent the specified written authorization, and addresses other confidential information and exceptions. It is not a property-condition disclosure.'],
  ['A buyer asks whether a prior occupant died naturally in the home, unrelated to property condition. No other facts create a duty. Which statement reflects §1101.556?', ['The statute does not impose a duty to inquire into or disclose that specified type of death; distinguish it from a condition-related hazard.', 'Every death must always be investigated and disclosed by the agent.', 'No physical hazard ever requires disclosure if a death is also mentioned.', 'The statute requires disclosure of an occupant’s HIV status.'], 'Section 1101.556 addresses the specified deaths and HIV/AIDS information. Its limited no-duty provisions do not erase duties about actual property conditions.']);
pair('T08U5', 'occupancy', '§ 92.010',
  ['A two-bedroom dwelling has four adults and three minor children. For §92.010’s general adult-count ceiling alone, how many adults are counted?', ['Four; the minor children are not adults for this provision.', 'Seven, because every person is counted as an adult.', 'Two, because only lease signers count.', 'Three, because a married couple always counts as one adult.'], 'Section 92.010 defines an adult as eighteen or older and provides a general adult ceiling of three times the bedrooms, subject to stated exceptions. It is not a universal cap of two persons per bedroom.'],
  ['A dwelling has three bedrooms plus a living room and kitchen. Under the general §92.010 calculation alone, before any statutory exception, what is the maximum number of adults?', ['Nine; living room and kitchen do not add statutory bedrooms.', 'Fifteen because every named room is a bedroom.', 'Six because Texas universally requires two adults per bedroom.', 'Three because only one adult per bedroom is allowed.'], 'The statute’s general ceiling is three adults per bedroom and excludes listed nonbedroom spaces. Other applicable standards and the statutory exceptions still require review; this computation is not a complete occupancy/fair-housing determination.']);

pair('T09U1', 'resale', 'Paragraphs 3 and 12B',
  ['In a new capstone file, price is $465,000 and agreed financing $372,000. A separate buyer fee is $9,300, with a $6,200 seller contribution. Which pair is correct before other closing adjustments?', ['$93,000 price cash and $3,100 uncovered brokerage fee.', '$99,200 price cash and zero uncovered fee.', '$372,000 price cash and $6,200 uncovered fee.', '$93,000 price cash and $9,300 additional seller contribution.'], 'Price cash is $465,000 minus $372,000; the uncovered fee is $9,300 minus $6,200. These separate calculations should not be blended into the price or mischaracterized as an automatic fee amendment.'],
  ['A revised capstone price is $538,000 and financing is $430,400. Buyer’s broker fee remains $10,000 and seller contributes $7,500. Which figures belong in the reconciliation?', ['$107,600 price cash and $2,500 remaining fee.', '$115,100 price cash and zero remaining fee.', '$430,400 cash and $17,500 total fee.', '$107,600 cash and $7,500 remaining fee.'], '$538,000 − $430,400 = $107,600; $10,000 − $7,500 = $2,500. The lender, price, and separate compensation records must remain consistent.'], '-A');
pair('T09U1', 'resale', 'Paragraphs 7F and 22',
  ['A capstone buyer requests repairs and a closing delay. Both parties effectively accept an amendment covering only the repairs. Which tracker is correct?', ['Add the accepted repair duties and retain the original closing date unless another effective change occurs.', 'Move closing to the requested date because some requests were accepted.', 'Cancel all original terms because an amendment exists.', 'Treat the unaccepted delay as an automatic option extension.'], 'An amendment changes the accepted terms it actually states. A partly successful negotiation does not adopt the rejected or omitted requests.'],
  ['The final repair invoice identifies the agreed work, but a qualified reinspection still reports the same defect. What should the capstone reviewer record?', ['Both the paperwork and the unresolved technical finding, followed by appropriate completion/remedy review and principal decision.', 'Complete compliance solely because an invoice exists.', 'Automatic buyer waiver because reinspection occurred.', 'A definitive agent guarantee that the trade provider is liable.'], 'Paragraph 7F addresses actual agreed completion as well as documentation. Record the discrepancy and use qualified technical/legal advice rather than treating paperwork as conclusive function.'], '-B');
pair('T09U1', 'resale', 'Paragraphs 9, 10 and 13',
  ['A capstone packet shows accepted terms, signed closing papers, and a pending-funding message. Possession is due at closing and funding. What unresolved event should remain on the final checklist?', ['Verified funding before treating the agreed possession trigger as fulfilled.', 'A second offer acceptance merely because closing papers exist.', 'A new option period starting when the buyer signs the deed of trust.', 'Automatic release of keys at the first closing signature regardless of funding.'], 'The form separates contract formation, closing tasks, funding, and possession. The final checklist should reflect the outstanding trigger instead of declaring completion too early.'],
  ['After a funded capstone closing, actual taxes differ from the estimate and the contract’s proration adjustment survives. What should the archive include?', ['The original estimate, actual bill, allocation calculation, and documented adjustment follow-up.', 'A deleted original settlement statement so the estimate cannot be compared.', 'An assumption that all duties vanished at funding.', 'A new purchase price invented to absorb the tax difference.'], 'Paragraph 13 provides the adjustment and survival. A transparent reconciliation preserves the history without rewriting the purchase price or concealing the estimate.'], '-C');

export const TOPIC_QUIZZES = Object.freeze(Object.fromEntries(TOPICS.map(topic => [topic.code,
  Object.freeze(rows.filter(([q]) => q.tests.startsWith(topic.code)).map(([q]) => q)),
])));
export const REPLACEMENTS = Object.freeze(Object.fromEntries(TOPICS.map(topic => [topic.code,
  Object.freeze(rows.filter(([q]) => q.tests.startsWith(topic.code)).map(([,r]) => r)),
])));
const REPLACEMENT_BY_PRIMARY = Object.freeze(Object.fromEntries(rows.map(([q, r]) => [q.id, r])));
// Alternate access is a function so inventory and public generators never count aliases as items.
export const replacementFor = primaryId => REPLACEMENT_BY_PRIMARY[primaryId];
export const PRIMARY_COUNT = rows.length;
export const REPLACEMENT_COUNT = Object.keys(REPLACEMENT_BY_PRIMARY).length;
const unitCodes = new Set(ALL_UNITS.map(unit => unit.code));
for (const [q, r] of rows) {
  for (const item of [q, r]) {
    if (!unitCodes.has(item.tests) || item.choices.length !== 4 || new Set(item.choices).size !== 4 || item.correctChoice !== 0 || !item.rationale || !item.section) throw new Error(`Invalid formative item ${item.id}`);
  }
  if (r.replaces !== q.id || r.prompt === q.prompt) throw new Error(`Invalid related replacement ${r.id}`);
}
for (const topic of TOPICS) {
  if (TOPIC_QUIZZES[topic.code].length < Math.max(3, topic.units.length)) throw new Error(`Insufficient primary items for ${topic.code}`);
  for (const unit of topic.units) if (!TOPIC_QUIZZES[topic.code].some(item => item.tests === unit.code)) throw new Error(`Untested official unit ${unit.code}`);
}
if (new Set(rows.flat().map(item => item.id)).size !== rows.length * 2) throw new Error('Duplicate formative item id');
